daily_metrics.content:
// Este código va en un Function node de n8n
// Se ejecuta diariamente para calcular KPIs

const yesterday = new Date();
yesterday.setDate(yesterday.getDate() - 1);
const dateStr = yesterday.toISOString().split('T')[0];

// Input: todas las citas del día anterior desde Google Sheets
const appointments = $input.all();

// Inicializar métricas
const metrics = {
  date: dateStr,
  formattedDate: yesterday.toLocaleDateString('es-MX', { 
    weekday: 'long', 
    year: 'numeric', 
    month: 'long', 
    day: 'numeric' 
  }),
  totalRevenue: 0,
  totalAppointments: appointments.length,
  avgTicket: 0,
  serviceBreakdown: {},
  barberPerformance: {},
  hourlyDistribution: {},
  noShows: 0,
  newCustomers: 0,
  paymentMethods: {}
};

// Procesar cada cita
appointments.forEach(apt => {
  const data = apt.json;

  // Revenue total
  if (data.status === 'completed' || data.status === 'confirmed') {
    metrics.totalRevenue += parseFloat(data.price) || 0;
  }

  // No-shows
  if (data.status === 'no_show') {
    metrics.noShows++;
  }

  // Breakdown por servicio
  const serviceName = data.serviceName;
  if (!metrics.serviceBreakdown[serviceName]) {
    metrics.serviceBreakdown[serviceName] = {
      count: 0,
      revenue: 0
    };
  }
  metrics.serviceBreakdown[serviceName].count++;
  metrics.serviceBreakdown[serviceName].revenue += parseFloat(data.price) || 0;

  // Performance por barbero
  const barberName = data.barber || 'Sin asignar';
  if (!metrics.barberPerformance[barberName]) {
    metrics.barberPerformance[barberName] = {
      appointments: 0,
      revenue: 0
    };
  }
  metrics.barberPerformance[barberName].appointments++;
  metrics.barberPerformance[barberName].revenue += parseFloat(data.price) || 0;

  // Distribución por hora
  const hour = data.time ? data.time.split(':')[0] : 'unknown';
  metrics.hourlyDistribution[hour] = (metrics.hourlyDistribution[hour] || 0) + 1;

  // Métodos de pago
  const paymentMethod = data.paymentMethod || 'no_especificado';
  metrics.paymentMethods[paymentMethod] = (metrics.paymentMethods[paymentMethod] || 0) + 1;
});

// Calcular ticket promedio
metrics.avgTicket = metrics.totalAppointments > 0 
  ? Math.round(metrics.totalRevenue / metrics.totalAppointments) 
  : 0;

// Top servicio
const servicesArray = Object.entries(metrics.serviceBreakdown)
  .sort((a, b) => b[1].revenue - a[1].revenue);
metrics.topService = servicesArray[0] ? servicesArray[0][0] : 'N/A';
metrics.topServiceRevenue = servicesArray[0] ? servicesArray[0][1].revenue : 0;
metrics.topServiceCount = servicesArray[0] ? servicesArray[0][1].count : 0;

// Top barbero
const barbersArray = Object.entries(metrics.barberPerformance)
  .sort((a, b) => b[1].revenue - a[1].revenue);
metrics.topBarber = barbersArray[0] ? barbersArray[0][0] : 'N/A';
metrics.topBarberRevenue = barbersArray[0] ? barbersArray[0][1].revenue : 0;

// Hora pico
const hoursArray = Object.entries(metrics.hourlyDistribution)
  .sort((a, b) => b[1] - a[1]);
metrics.peakHour = hoursArray[0] ? `${hoursArray[0][0]}:00` : 'N/A';

return [{ json: metrics }];

format_daily_report.content:
// Recibe las métricas del nodo anterior y genera mensaje formateado

const data = $input.first().json;

// Función helper para formato de moneda
function formatMoney(amount) {
  return `$${Math.round(amount).toLocaleString('es-MX')} MXN`;
}

// Construir lista de top servicios
const topServicesText = Object.entries(data.serviceBreakdown)
  .sort((a, b) => b[1].count - a[1].count)
  .slice(0, 3)
  .map((entry, i) => {
    const emoji = ['🥇', '🥈', '🥉'][i];
    return `   ${emoji} ${entry[0]}: ${entry[1].count} citas (${formatMoney(entry[1].revenue)})`;
  })
  .join('\n');

// Construir lista de barberos
const barbersText = Object.entries(data.barberPerformance)
  .sort((a, b) => b[1].revenue - a[1].revenue)
  .map((entry, i) => {
    const emoji = i === 0 ? '⭐' : '💈';
    return `   ${emoji} ${entry[0]}: ${entry[1].appointments} citas (${formatMoney(entry[1].revenue})})`;
  })
  .join('\n');

// Calcular indicadores (ejemplo: comparación con promedio)
const avgRevenue = 1500; // Esto idealmente viene de histórico
const growthPercent = ((data.totalRevenue - avgRevenue) / avgRevenue * 100).toFixed(1);
const growthEmoji = growthPercent >= 0 ? '📈' : '📉';

const message = `
╔════════════════════════════════════════╗
║  📊 REPORTE DIARIO - BARBERÍA PINZÓN  ║
╚════════════════════════════════════════╝

📅 *Fecha:* ${data.formattedDate}

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

💰 *RESUMEN FINANCIERO*

   Total del día: *${formatMoney(data.totalRevenue)}*
   Citas atendidas: *${data.totalAppointments}*
   Ticket promedio: *${formatMoney(data.avgTicket)}*

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

🔥 *SERVICIOS MÁS VENDIDOS*

${topServicesText}

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

💈 *PERFORMANCE POR BARBERO*

${barbersText}

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

⚠️ *INDICADORES*

   No-shows: ${data.noShows}
   Hora pico: ${data.peakHour}

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

${growthEmoji} *Comparado con promedio:* ${growthPercent > 0 ? '+' : ''}${growthPercent}%

${data.totalRevenue > avgRevenue ? '✨ ¡Excelente día de trabajo!' : '💪 Sigue así, cada día cuenta'}

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

🔍 *Comandos disponibles:*
   👉 "REPORTE SEMANAL"
   👉 "REPORTE MENSUAL"
   👉 "TOP CLIENTES"
`;

return [{ 
  json: { 
    message: message,
    metrics: data,
    timestamp: new Date().toISOString()
  } 
}];

check_calendar_availability.content:
// Verifica si un slot de tiempo está disponible
// Input: fecha, hora, duración del servicio
// Output: disponible (true/false) + alternativas si está ocupado

const requestedDate = $json.date; // 'YYYY-MM-DD'
const requestedTime = $json.time; // 'HH:MM'
const serviceDuration = parseInt($json.duration); // minutos
const barber = $json.barber || null; // opcional

// Convertir a timestamps para comparación
const requestedStart = new Date(`${requestedDate}T${requestedTime}:00`);
const requestedEnd = new Date(requestedStart.getTime() + serviceDuration * 60000);

// Eventos existentes del calendario (viene de nodo anterior Google Calendar)
const existingEvents = $('Google Calendar').all().map(item => item.json);

// Función para verificar overlap
function hasOverlap(event) {
  const eventStart = new Date(event.start.dateTime);
  const eventEnd = new Date(event.end.dateTime);

  return (
    (requestedStart >= eventStart && requestedStart < eventEnd) ||
    (requestedEnd > eventStart && requestedEnd <= eventEnd) ||
    (requestedStart <= eventStart && requestedEnd >= eventEnd)
  );
}

// Verificar si hay conflicto
const conflicts = existingEvents.filter(hasOverlap);
const isAvailable = conflicts.length === 0;

let alternatives = [];

if (!isAvailable) {
  // Generar alternativas: buscar slots libres cercanos
  const searchRange = 7; // buscar en próximos 7 días
  const workingHours = [
    { start: 10, end: 20 } // 10 AM a 8 PM
  ];

  for (let dayOffset = 0; dayOffset < searchRange && alternatives.length < 3; dayOffset++) {
    const checkDate = new Date(requestedDate);
    checkDate.setDate(checkDate.getDate() + dayOffset);

    // Skip domingos (día 0)
    if (checkDate.getDay() === 0) continue;

    for (let hour = workingHours[0].start; hour < workingHours[0].end && alternatives.length < 3; hour++) {
      const checkStart = new Date(checkDate);
      checkStart.setHours(hour, 0, 0, 0);
      const checkEnd = new Date(checkStart.getTime() + serviceDuration * 60000);

      // Verificar si este slot está libre
      const hasConflict = existingEvents.some(event => {
        const eventStart = new Date(event.start.dateTime);
        const eventEnd = new Date(event.end.dateTime);
        return (
          (checkStart >= eventStart && checkStart < eventEnd) ||
          (checkEnd > eventStart && checkEnd <= eventEnd)
        );
      });

      if (!hasConflict) {
        alternatives.push({
          date: checkDate.toISOString().split('T')[0],
          time: `${hour.toString().padStart(2, '0')}:00`,
          formatted: `${checkDate.toLocaleDateString('es-MX', { weekday: 'long', day: 'numeric', month: 'long' })} a las ${hour > 12 ? hour - 12 : hour}:00 ${hour >= 12 ? 'PM' : 'AM'}`
        });
      }
    }
  }
}

return [{
  json: {
    isAvailable: isAvailable,
    requestedSlot: {
      date: requestedDate,
      time: requestedTime,
      duration: serviceDuration
    },
    conflicts: conflicts.length,
    alternatives: alternatives,
    message: isAvailable 
      ? 'Slot disponible' 
      : `Slot ocupado. ${alternatives.length} alternativas encontradas`
  }
}];

appointment_validation:
name": "Validación de Datos de Cita",
      "schema": {
        "customerName": {
          "required": true,
          "type": "string",
          "minLength": 3,
          "pattern": "^[a-zA-ZáéíóúÁÉÍÓÚñÑ ]+$",
          "errorMessage": "El nombre debe tener al menos 3 caracteres y solo letras"
        },
        "phoneNumber": {
          "required": true,
          "type": "string",
          "pattern": "^\\+52[0-9]{10}$",
          "errorMessage": "El teléfono debe tener formato +52 seguido de 10 dígitos"
        },
        "serviceId": {
          "required": true,
          "type": "string",
          "pattern": "^SRV-[0-9]{3}$",
          "errorMessage": "ID de servicio inválido"
        },
        "appointmentDate": {
          "required": true,
          "type": "string",
          "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$",
          "validation": "debe ser fecha futura",
          "errorMessage": "Fecha debe estar en formato YYYY-MM-DD y ser fecha futura"
        },
        "appointmentTime": {
          "required": true,
          "type": "string",
          "pattern": "^([0-1][0-9]|2[0-3]):[0-5][0-9]$",
          "validation": "debe estar entre 10:00 y 20:00",
          "errorMessage": "Hora debe estar en formato HH:MM (24h) entre 10:00 y 20:00"
        }
      },
      "validationCode": "const errors = [];\nif (!data.customerName || data.customerName.length < 3) errors.push('Nombre inválido');\nif (!data.phoneNumber || !/^\\+52[0-9]{10}$/.test(data.phoneNumber)) errors.push('Teléfono inválido');\nconst aptDate = new Date(data.appointmentDate);\nif (aptDate < new Date()) errors.push('Fecha debe ser futura');\nconst hour = parseInt(data.appointmentTime.split(':')[0]);\nif (hour < 10 || hour >= 20) errors.push('Horario fuera de servicio');\nreturn { valid: errors.length === 0, errors: errors };"
    }
  },

  "workflow_templates": {
    "reminder_24h": {
      "name": "Recordatorio 24 Horas Antes",
      "trigger": "Schedule Trigger - cada hora",
      "description": "Busca citas que son en 24 horas y envía recordatorio",
      "nodes": [
        {
          "type": "Schedule Trigger",
          "config": { "cron": "0 * * * *" },
          "note": "Ejecuta cada hora"
        },
        {
          "type": "Function",
          "name": "Calcular Ventana de Tiempo",
          "code": "const now = new Date();\nconst in24h = new Date(now.getTime() + 24 * 60 * 60 * 1000);\nconst in25h = new Date(now.getTime() + 25 * 60 * 60 * 1000);\nreturn [{ json: { startTime: in24h.toISOString(), endTime: in25h.toISOString() } }];"
        },
        {
          "type": "Google Sheets",
          "operation": "Read",
          "config": {
            "sheetName": "Citas",
            "filter": "status = 'confirmed' AND reminderSent24h = FALSE"
          }
        },
        {
          "type": "Function",
          "name": "Filtrar Citas en Ventana",
          "code": "const appointments = $input.all();\nconst start = new Date($('Calcular Ventana de Tiempo').first().json.startTime);\nconst end = new Date($('Calcular Ventana de Tiempo').first().json.endTime);\nreturn appointments.filter(apt => {\n  const aptTime = new Date(`${apt.json.date}T${apt.json.time}:00`);\n  return aptTime >= start && aptTime < end;\n});"
        },
        {
          "type": "Function",
          "name": "Generar Mensaje Recordatorio",
          "code": "const apt = $input.first().json;\nconst message = `🔔 *RECORDATORIO DE CITA*\n\nHola ${apt.customerName}! 👋\n\nTe recordamos tu cita en:\n📅 *${apt.date}*\n🕒 *${apt.time}*\n\n✂️ Servicio: ${apt.serviceName}\n💵 Costo: $${apt.price} MXN\n📍 Calle Pinzón #574\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n⚠️ Si no podrás asistir, avísanos:\n   Escribe \"CANCELAR ${apt.appointmentId}\"\n\n¡Te esperamos! 💈`;\nreturn [{ json: { phone: apt.customerPhone, message: message, appointmentId: apt.appointmentId } }];"
        },
        {
          "type": "WhatsApp",
          "operation": "Send Message",
          "config": "{{$json.phone}}"
        },
        {
          "type": "Google Sheets",
          "operation": "Update",
          "config": {
            "sheetName": "Citas",
            "updateFields": { "reminderSent24h": true, "reminderSent24hAt": "={{$now}}" }
          }
        }
      ]
    }
  },

  "best_practices": {
    "prompt_optimization": [
      "Siempre incluye ejemplos concretos en prompts de clasificación",
      "Usa Chain-of-Thought para tareas de extracción complejas",
      "Especifica formato de salida exacto (JSON schema)",
      "Incluye reglas de manejo de errores en el prompt",
      "Mantén prompts bajo 500 tokens cuando sea posible",
      "Usa variables de contexto para personalización",
      "Testea prompts con casos edge (inputs ambiguos)"
    ],
    "workflow_design": [
      "Separar workflows por funcionalidad (modularidad)",
      "Implementar retry logic para APIs externas",
      "Siempre logear interacciones para debugging",
      "Usar Function nodes para lógica compleja en lugar de múltiples nodos",
      "Validar datos críticos antes de crear registros",
      "Implementar timeouts apropiados (30s para AI, 10s para APIs)",
      "Usar variables de entorno para credenciales"
    ],
    "user_experience": [
      "Máximo 3 opciones por pregunta de múltiple elección",
      "Siempre confirmar datos críticos antes de acciones irreversibles",
      "Proporcionar feedback inmediato (ej: 'Buscando disponibilidad...')",
      "Usar emojis contextualmente, no decorativamente",
      "Mantener consistencia en tono y formato",
      "Incluir siempre próximo paso claro en cada mensaje",
      "Proporcionar código/ID de referencia para citas"
    ]
  }
}
